                </div>
            </div>
            <div class="debug-panel">
                <div class="debug-section">
                    <h3>Current Instruction</h3>
                    <div class="instruction-info">
                        <div>PC: <span id="pcValue" class="debug-value">0x0000</span></div>
                        <div>Opcode: <span id="opcodeValue" class="debug-value">0x0000</span></div>
                        <div id="instructionDescription">-</div>
                    </div>
                </div>
                <div class="debug-section">
                    <h3>Registers</h3>
                    <div class="registers-grid" id="registersGrid"></div>
                </div>
                <div class="debug-section">
                    <h3>System Registers</h3>
                    <div><strong>I:</strong> <span id="indexValue" class="debug-value">0x0000</span></div>
                    <div><strong>Delay:</strong> <span id="delayValue" class="debug-value">0</span></div>
                    <div><strong>Sound:</strong> <span id="soundValue" class="debug-value">0</span></div>
