                <div class="debug-section">
                    <h3>Memory (0x200-0x2FF)</h3>
                    <div class="memory-view" id="memoryView"></div>
                </div>
            </div>
        </div>
    </div>

    <script>
        // CHIP-8 Emulator Implementation
        class Chip8 {
            constructor() {
                // Memory: 4KB
                this.memory = new Uint8Array(4096);

                // Registers V0-VF (16 registers)
                this.v = new Uint8Array(16);

                // Index register (16-bit)
                this.i = 0;

                // Program counter
                this.pc = 0x200;

                // Stack
                this.stack = new Uint16Array(16);
                this.sp = 0;

                // Timers
                this.delayTimer = 0;
                this.soundTimer = 0;

                // Display: 64x32 pixels
                this.display = new Uint8Array(64 * 32);

                // Keypad (16 keys)
                this.keys = new Uint8Array(16);

                // Draw flag
                this.drawFlag = false;

                // Current instruction being executed
                this.currentOpcode = 0;
                this.instructionDescription = '';

                // Load font set at 0x050
                this.loadFontSet();
            }

            loadFontSet() {
                const fonts = [
                    0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
                    0x20, 0x60, 0x20, 0x20, 0x70, // 1
                    0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
                    0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
                    0x90, 0x90, 0xFF, 0x10, 0x10, // 4
                    0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
                    0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
                    0xF0, 0x10, 0x20, 0x40, 0x40, // 7
                    0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
                    0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
                    0xF0, 0x90, 0xF0, 0x90, 0x90, // A
                    0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
                    0xF0, 0x80, 0x80, 0x80, 0xF0, // C
                    0xE0, 0x90, 0x90, 0x90, 0xE0, // D
                    0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
                    0xF0, 0x80, 0xF0, 0x80, 0x80  // F
                ];
                for (let i = 0; i < fonts.length; i++) {
                    this.memory[0x050 + i] = fonts[i];
                }
            }

            reset() {
                this.v.fill(0);
                this.i = 0;
                this.pc = 0x200;
                this.stack.fill(0);
                this.sp = 0;
                this.delayTimer = 0;
                this.soundTimer = 0;
                this.display.fill(0);
                this.keys.fill(0);
                this.drawFlag = true;
                this.currentOpcode = 0;
                this.instructionDescription = '';
            }

            loadROM(romData) {
                // Clear memory except fontset
                for (let i = 0x200; i < 4096; i++) {
                    this.memory[i] = 0;
                }

                // Load ROM at 0x200
                for (let i = 0; i < romData.length && i < 0xE00; i++) {
                    this.memory[0x200 + i] = romData[i];
                }
            }

            decodeAndExecute() {
                // Fetch opcode (2 bytes, big-endian)
                const byte1 = this.memory[this.pc];
                const byte2 = this.memory[this.pc + 1];
                this.currentOpcode = (byte1 << 8) | byte2;

                // Decode and execute
                const x = (this.currentOpcode >> 8) & 0x0F;
                const y = (this.currentOpcode >> 4) & 0x0F;
                const n = this.currentOpcode & 0x0F;
                const nn = this.currentOpcode & 0xFF;
                const nnn = this.currentOpcode & 0xFFF;

                // Clear VF before instruction
                this.v[15] = 0;

                switch (byte1 & 0xF0) {
                    case 0x00:
                        switch (this.currentOpcode & 0x0FF) {
                            case 0x0E0: // 00E0: Clear display
                                this.display.fill(0);
                                this.drawFlag = true;
                                this.instructionDescription = 'CLS - Clear display';
                                break;
                            case 0x0EE: // 00EE: Return from subroutine
                                this.sp--;
                                this.pc = this.stack[this.sp];
                                this.instructionDescription = 'RET - Return from subroutine';
                                break;
                            default:
                                // 0NNN: Call machine code routine (not used)
                                this.instructionDescription = `SYS - Machine code call 0x${this.currentOpcode.toString(16).padStart(4, '0')}`;
                                break;
                        }
                        break;

                    case 0x10: // 1NNN: Jump to address NNN
                        this.pc = nnn;
                        this.instructionDescription = `JMP - Jump to 0x${nnn.toString(16).padStart(3, '0')}`;
                        return false; // Don't increment PC
                    case 0x20: // 2NNN: Call subroutine at NNN
                        this.stack[this.sp] = this.pc;
                        this.sp++;
                        this.pc = nnn;
                        this.instructionDescription = `CALL - Call subroutine 0x${nnn.toString(16).padStart(3, '0')}`;
                        return false; // Don't increment PC
                    case 0x30: // 3XNN: Skip if VX == NN
                        this.pc += (this.v[x] === nn) ? 2 : 0;
                        this.instructionDescription = `SE V${x.toString(16)}, ${nn.toString(16)} - Skip if equal`;
                        break;
                    case 0x40: // 4XNN: Skip if VX != NN
                        this.pc += (this.v[x] !== nn) ? 2 : 0;
                        this.instructionDescription = `SNE V${x.toString(16)}, ${nn.toString(16)} - Skip if not equal`;
                        break;
                    case 0x50: // 5XY0: Skip if VX == VY
                        this.pc += (this.v[x] === this.v[y]) ? 2 : 0;
                        this.instructionDescription = `SE V${x.toString(16)}, V${y.toString(16)} - Skip if equal`;
                        break;
                    case 0x60: // 6XNN: Set VX = NN
                        this.v[x] = nn;
                        this.pc += 2;
                        this.instructionDescription = `LD V${x.toString(16)}, ${nn.toString(16)} - Load immediate`;
                        return false;
                    case 0x70: // 7XNN: Add NN to VX (no VF)
                        this.v[x] += nn;
                        this.pc += 2;
                        this.instructionDescription = `ADD V${x.toString(16)}, ${nn.toString(16)} - Add immediate`;
                        return false;
                    case 0x80:
                        switch (n) {
                            case 0x0: // 8XY0: Set VX = VY
                                this.v[x] = this.v[y];
                                this.instructionDescription = `LD V${x.toString(16)}, V${y.toString(16)} - Move register`;
                                break;
                            case 0x1: // 8XY1: Set VX = VX OR VY
                                this.v[x] |= this.v[y];
                                this.instructionDescription = `OR V${x.toString(16)}, V${y.toString(16)} - Bitwise OR`;
                                break;
                            case 0x2: // 8XY2: Set VX = VX AND VY
                                this.v[x] &= this.v[y];
                                this.instructionDescription = `AND V${x.toString(16)}, V${y.toString(16)} - Bitwise AND`;
                                break;
                            case 0x3: // 8XY3: Set VX = VX XOR VY
                                this.v[x] ^= this.v[y];
                                this.instructionDescription = `XOR V${x.toString(16)}, V${y.toString(16)} - Bitwise XOR`;
                                break;
                            case 0x4: // 8XY4: Add VY to VX, VF = carry
                                const sum = this.v[x] + this.v[y];
                                this.v[x] = sum & 0xFF;
                                this.v[15] = (sum > 255) ? 1 : 0;
                                this.instructionDescription = `ADD V${x.toString(16)}, V${y.toString(16)} - Add with carry`;
                                break;
                            case 0x5: // 8XY5: Subtract VY from VX, VF = NOT borrow
                                const sub = this.v[x] - this.v[y];
                                this.v[x] = sub & 0xFF;
                                this.v[15] = (this.v[x] >= this.v[y]) ? 1 : 0;
                                this.instructionDescription = `SUB V${x.toString(16)}, V${y.toString(16)} - Subtract with borrow`;
                                break;
                            case 0x6: // 8XY6: Shift VX right, VF = LSB
                                const lsb = this.v[x] & 0x1;
                                this.v[x] = Math.floor(this.v[x] / 2);
                                this.v[15] = lsb;
                                this.instructionDescription = `SHR V${x.toString(16)} - Shift right`;
                                break;
                            case 0x7: // 8XY7: Set VX = VY - VX, VF = NOT borrow
                                const diff = this.v[y] - this.v[x];
                                this.v[x] = diff & 0xFF;
                                this.v[15] = (this.v[y] >= this.v[x]) ? 1 : 0;
                                this.instructionDescription = `SUBN V${x.toString(16)}, V${y.toString(16)} - Subtract reverse`;
                                break;
                            case 0xE: // 8XYE: Shift VX left, VF = MSB
                                const msb = (this.v[x] & 0x80) >> 7;
                                this.v[x] = (this.v[x] << 1) & 0xFF;
                                this.v[15] = msb;
                                this.instructionDescription = `SHL V${x.toString(16)} - Shift left`;
                                break;
                            default:
                                this.instructionDescription = `Unknown opcode 0x${this.currentOpcode.toString(16).padStart(4, '0')}`;
                        }
                        break;

                    case 0x90: // 9XY0: Skip if VX != VY
                        this.pc += (this.v[x] !== this.v[y]) ? 2 : 0;
                        this.instructionDescription = `SNE V${x.toString(16)}, V${y.toString(16)} - Skip if not equal`;
                        break;

                    case 0xA0: // ANNN: Set I = NNN
                        this.i = nnn;
                        this.instructionDescription = `LD I, ${nnn.toString(16)} - Load index register`;
                        break;

                    case 0xB0: // BNNN: Jump to V0 + NNN
                        this.pc = this.v[0] + nnn;
                        this.instructionDescription = `JRP V0+${nnn.toString(16)} - Jump relative`;
                        return false;

                    case 0xC0: // CXNN: Set VX = random & NN
                        this.v[x] = (Math.floor(Math.random() * 256)) & nn;
                        this.instructionDescription = `RND V${x.toString(16)}, ${nn.toString(16)} - Random`;
                        break;

                    case 0xD0: // DXYN: Draw sprite at (VX, VY), N rows
                        let collision = false;
                        for (let row = 0; row < n; row++) {
                            const spriteByte = this.memory[this.i + row];
                            const drawY = (this.v[y] + row) % 32;
                            for (let col = 0; col < 8; col++) {
                                if ((spriteByte & (0x80 >> col)) !== 0) {
                                    const px = (this.v[x] + col) % 64;
                                    const idx = drawY * 64 + px;
                                    if (this.display[idx] === 1) {
                                        collision = true;
                                    }
                                    this.display[idx] ^= 1;
                                }
                            }
                        }
                        this.v[15] = collision ? 1 : 0;
                        this.drawFlag = true;
                        this.instructionDescription = `DRW V${x.toString(16)}, V${y.toString(16)}, ${n} - Draw sprite`;
                        break;

                    case 0xE0:
                        switch (this.currentOpcode & 0xFF) {
                            case 0x9E: // EX9E: Skip if key VX is pressed
                                this.pc += (this.keys[this.v[x]] === 1) ? 2 : 0;
                                this.instructionDescription = `SKP V${x.toString(16)} - Skip if key pressed`;
                                break;
                            case 0xA1: // EXA1: Skip if key VX is not pressed
                                this.pc += (this.keys[this.v[x]] === 0) ? 2 : 0;
                                this.instructionDescription = `SKNP V${x.toString(16)} - Skip if key not pressed`;
                                break;
                            default:
                                this.instructionDescription = `Unknown opcode 0x${this.currentOpcode.toString(16).padStart(4, '0')}`;
                        }
                        break;

                    case 0xF0:
                        switch (nn) {
                            case 0x07: // FX07: Set VX = delay timer
                                this.v[x] = this.delayTimer;
                                this.instructionDescription = `LD V${x.toString(16)}, DT - Load delay timer`;
                                break;
                            case 0x0A: // FX0A: Wait for key press, store in VX
                                let pressed = false;
                                for (let k = 0; k < 16; k++) {
                                    if (this.keys[k] === 1) {
                                        this.v[x] = k;
                                        pressed = true;
                                        break;
                                    }
                                }
                                if (!pressed) return false; // Wait for key
                                this.instructionDescription = `LD V${x.toString(16)}, K - Wait for key press`;
                                break;
                            case 0x15: // FX15: Set delay timer = VX
                                this.delayTimer = this.v[x];
                                this.instructionDescription = `LD DT, V${x.toString(16)} - Set delay timer`;
                                break;
                            case 0x18: // FX18: Set sound timer = VX
                                this.soundTimer = this.v[x];
                                this.instructionDescription = `LD ST, V${x.toString(16)} - Set sound timer`;
                                break;
                            case 0x1E: // FX1E: Add VX to I
                                this.i += this.v[x];
                                this.instructionDescription = `ADD I, V${x.toString(16)} - Add to index`;
                                break;
                            case 0x29: // FX29: Set I = sprite for digit VX
                                this.i = 5 * this.v[x];
                                this.instructionDescription = `LD I, F[V${x.toString(16)}] - Font sprite address`;
                                break;
                            case 0x33: // FX33: Store BCD of VX at I, I+1, I+2
                                this.memory[this.i] = Math.floor(this.v[x] / 100);
                                this.memory[this.i + 1] = Math.floor((this.v[x] % 100) / 10);
                                this.memory[this.i + 2] = this.v[x] % 10;
                                this.instructionDescription = `LD BCD, V${x.toString(16)} - Store BCD`;
                                break;
                            case 0x55: // FX55: Store V0-VX in memory at I
                                for (let idx = 0; idx <= x; idx++) {
                                    this.memory[this.i + idx] = this.v[idx];
                                }
                                this.instructionDescription = `LD [I], V${x.toString(16)} - Store registers`;
                                break;
                            case 0x65: // FX65: Load V0-VX from memory at I
                                for (let idx = 0; idx <= x; idx++) {
                                    this.v[idx] = this.memory[this.i + idx];
                                }
                                this.instructionDescription = `LD V${x.toString(16)}, [I] - Load registers`;
                                break;
                            default:
                                this.instructionDescription = `Unknown opcode 0x${this.currentOpcode.toString(16).padStart(4, '0')}`;
                        }
                        break;

                    default:
                        this.instructionDescription = `Unknown opcode 0x${this.currentOpcode.toString(16).padStart(4, '0')}`;
                }

                // Increment PC by 2 (unless jump/call modified it)
                if (this.pc === (byte1 << 8 | byte2 >> 8)) {
                    this.pc += 2;
                }

                return true;
            }

            updateTimers() {
                if (this.delayTimer > 0) {
                    this.delayTimer--;
                }
                if (this.soundTimer > 0) {
                    this.soundTimer--;
                }
            }
        }

        // Demo ROM: Moving sprite that reacts to keys
        // Instructions:
        // - Draws a simple sprite at position V0, V1
        // - Moves right with '1' key, left with 'Q' key
        // - Up with 'A' key, down with 'Z' key
        const DEMO_ROM = [
            // Initialize registers
            0x60, 0x28,    // V0 = 40 (start X)
            0x61, 0x10,    // V1 = 16 (start Y)
            0x62, 0x0A,    // V2 = 10 (sprite width for loop)

            // Main loop label
            0x3D, 0x00,    // Skip if VF == 0 (collision check - not used here)

            // Draw sprite at V0, V1
            0xA2, 0x050,   // I = font set address (using first character as demo sprite)
            0xD0, 0x13,    // Draw sprite at (V0, V1), 3 rows

            // Wait for key press or check keys
            0xE0, 0xA1,    // Skip if key in V0 is not pressed
            0x64, 0x01,    // Set V4 = 1 (direction)

            0x30, 0x01,    // Skip if V0 == 1 (key '1' pressed - move right)
            0x60, 0x01,    // V0 += 1

            0x30, 0x0A,    // Skip if key 'Q' not pressed (move left)
            0x70, 0xFF,    // V0 -= 1

            // Simple delay
            0xF0, 0x15,    // DT = V0
            0x3D, 0x00,    // Skip while timer > 0

            // Jump back to start
            0x20, 0x200    // Call main (effectively jump)
        ];

        // UI and emulator control
        const canvas = document.getElementById('displayCanvas');
        const ctx = canvas.getContext('2d');
        const chip8 = new Chip8();

        let running = false;
        let stepping = false;
        let speed = 30; // instructions per frame
        let animationId = null;
        let lastTime = 0;
        let accumulator = 0;

        // Initialize display
        function initDisplay() {
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            updateDisplay();
            updateDebugger();
        }

        // Update display on canvas
        function updateDisplay() {
            if (!chip8.drawFlag) return;

            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#e94560';

            for (let y = 0; y < 32; y++) {
                for (let x = 0; x < 64; x++) {
                    if (chip8.display[y * 64 + x]) {
                        ctx.fillRect(x, y, 1, 1);
                    }
                }
            }

