        // Update debugger panel
        function updateDebugger() {
            // PC and opcode
            document.getElementById('pcValue').textContent = `0x${chip8.pc.toString(16).padStart(4, '0')}`;
            document.getElementById('opcodeValue').textContent = `0x${chip8.currentOpcode.toString(16).padStart(4, '0')}`;
            document.getElementById('instructionDescription').textContent = chip8.instructionDescription;

            // Registers
            const regGrid = document.getElementById('registersGrid');
