        // Keyboard mapping for CHIP-8 keypad
        const keyMap = {
            '1': 0, '2': 1, '3': 2, '4': 3,
            'q': 0x0a, 'w': 0x0b, 'e': 0x0c, 'r': 0x0d,
            'a': 4, 's': 5, 'd': 6, 'f': 7,
            'z': 0x14, 'x': 0x15, 'c': 0x16, 'v': 0x17
        };

        // Visual key mapping
        const visualKeyMap = {
            '1': '0', '2': '1', '3': '2', '4': '3',
            'q': '0x0a', 'w': '0x0b', 'e': '0x0c', 'r': '0x0d',
            'a': '4', 's': '5', 'd': '6', 'f': '7',
            'z': '0x14', 'x': '0x15', 'c': '0x16', 'v': '0x17'
        };

        // Keydown handler
        document.addEventListener('keydown', function(e) {
            const key = e.key.toLowerCase();
            if (keyMap[key] !== undefined && !e.repeat) {
                chip8.keys[keyMap[key]] = 1;
                document.querySelector(`.key[data-key="${visualKeyMap[key]}"]`).classList.add('active');
                e.preventDefault();
            }
        });

        // Keyup handler
        document.addEventListener('keyup', function(e) {
            const key = e.key.toLowerCase();
            if (keyMap[key] !== undefined) {
                chip8.keys[keyMap[key]] = 0;
                document.querySelector(`.key[data-key="${visualKeyMap[key]}"]`).classList.remove('active');
            }
        });

        // Initialize with demo ROM
        loadDemoROM();
